use xiom.io;

use xiom.string;
type Table = {
  name: Str;
  rows: Vec[Map[Str, Str]];
}

fn Table.new(name: Str) -> Table {
  return Table{ name: name, rows: Vec[Map[Str, Str]].new() };
}

fn Table.insert(t: &mut Table, row: Map[Str, Str]) {
  t.rows.push(row);
}

fn Table.find_by(t: &Table, column: Str, value: Str) -> Vec[Map[Str, Str]] {
  let matched: Vec[Map[Str, Str]] = Vec[Map[Str, Str]].new();
  let i = 0;
  while i < t.rows.len() {
    let row = t.rows[i];
    let cell = match row.get(column) { Some(v) => v, None => "" };
    if cell == value {
      matched.push(row);
    }
    i = i + 1;
  }
  return matched;
}

fn Table.count(t: &Table) -> Int {
  return t.rows.len();
}

fn main() -> Int {
  var db: Table = Table.new("inventory");

  var r1: Map[Str, Str] = Map[Str, Str].new();
  r1.insert("item", "apple");
  r1.insert("qty", "50");
  db.insert(r1);

  var r2: Map[Str, Str] = Map[Str, Str].new();
  r2.insert("item", "banana");
  r2.insert("qty", "30");
  db.insert(r2);

  let apples = db.find_by("item", "apple");
  io.println(to_string(apples.len()));
  io.println(to_string(db.count()));
  return 0;
}
